def countKingWalks(board, k):
    MOD = 10 ** 9 + 7
    m, n = len(board), len(board[0])
    if board[0][0] == 1 or board[m - 1][n - 1] == 1:
        return 0
    cur = [[0] * n for _ in range(m)]
    cur[0][0] = 1
    for _ in range(k):
        nxt = [[0] * n for _ in range(m)]
        for r in range(m):
            for c in range(n):
                if board[r][c] == 1:
                    continue
                s = 0
                for dr in (-1, 0, 1):
                    a = r + dr
                    if 0 <= a < m:
                        row = cur[a]
                        for dc in (-1, 0, 1):
                            b = c + dc
                            if (dr or dc) and 0 <= b < n:
                                s += row[b]
                nxt[r][c] = s % MOD
        cur = nxt
    return cur[m - 1][n - 1]
